}

/// Vector detail overlay. kind: 0 dark line, 1 dark fill, 2 white line,
/// 3 white fill, 4 blush fill. Drawn crisp over the dots and follows the warp.
class DetailSpec {
  const DetailSpec(this.kind, this.path, this.width, [this.tag = '']);
  final int kind;
  final String path;
  final double width;
  /// 'mouth' / 'brow' strokes are hidden while an expression is active.
  final String tag;
}

class AnimalArt {
  const AnimalArt(this.layers, this.eyes, this.cheeks, this.details);
